"""HTTP client for talking to a REST API."""

from __future__ import annotations

from typing import Any, Mapping, Optional

import requests


class ApiError(Exception):
    """Raised when the API returns an error response."""

    def __init__(self, message: str, status_code: Optional[int] = None) -> None:
        super().__init__(message)
        self.status_code = status_code


class ApiClient:
    """Thin wrapper around :mod:`requests` for a JSON REST API."""

    def __init__(
        self,
        base_url: str,
        *,
        timeout: float = 10.0,
        headers: Optional[Mapping[str, str]] = None,
        session: Optional[requests.Session] = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.session = session or requests.Session()
        self.session.headers.update({"Accept": "application/json"})
        if headers:
            self.session.headers.update(headers)

    def get(self, path: str, params: Optional[Mapping[str, Any]] = None) -> Any:
        """GET ``path`` and return the decoded JSON body."""
        url = path if path.startswith(("http://", "https://")) else f"{self.base_url}/{path.lstrip('/')}"
        try:
            response = self.session.get(url, params=params, timeout=self.timeout)
        except requests.RequestException as exc:
            raise ApiError(f"request to {url} failed: {exc}") from exc

        if not response.ok:
            raise ApiError(
                f"GET {url} returned {response.status_code}",
                status_code=response.status_code,
            )

        try:
            return response.json()
        except ValueError as exc:
            raise ApiError(f"response from {url} was not valid JSON") from exc

    def close(self) -> None:
        self.session.close()

    def __enter__(self) -> "ApiClient":
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.close()

from api_fetcher.client import ApiClient, ApiError


class FakeResponse:
    def __init__(self, payload, status_code=200):
        self._payload = payload
        self.status_code = status_code

    @property
    def ok(self):
        return self.status_code < 400

    def json(self):
        if isinstance(self._payload, Exception):
            raise self._payload
        return self._payload


class FakeSession:
    def __init__(self, response):
        self.response = response
        self.headers = {}
        self.calls = []

    def get(self, url, params=None, timeout=None):
        self.calls.append((url, params, timeout))
        return self.response

    def close(self):
        pass


def test_get_returns_json():
    session = FakeSession(FakeResponse({"ok": True}))
    client = ApiClient("https://example.com/api", session=session)

    assert client.get("users", params={"page": 1}) == {"ok": True}
    assert session.calls[0][0] == "https://example.com/api/users"
    assert session.calls[0][1] == {"page": 1}


def test_get_raises_on_error_status():
    session = FakeSession(FakeResponse({"error": "nope"}, status_code=404))
    client = ApiClient("https://example.com/api", session=session)

    try:
        client.get("missing")
    except ApiError as exc:
        assert exc.status_code == 404
    else:
        raise AssertionError("ApiError was not raised")


def test_full_url_is_used_as_is():
    session = FakeSession(FakeResponse([]))
    client = ApiClient("https://example.com/api", session=session)

    client.get("https://other.example/items")
    assert session.calls[0][0] == "https://other.example/items"

